import logging

from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import \
    Validator
from taf.fdsw.rc.schemas.FDSW23B.autoconnection_parameters_builder_23b import AutoconnectionParametersBuilder23B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoconnectionParametersBuilder23C(AutoconnectionParametersBuilder23B):
    def __init__(self, **kwargs):
        super(AutoconnectionParametersBuilder23C, self).__init__(**kwargs)

        if 'cmp_security_gateway_ip_address' in kwargs:
            cmp_security_gateway_ip_address = kwargs['cmp_security_gateway_ip_address']
            self.certifcate_parameters.update(cmpSecurityGatewayIpAddress=cmp_security_gateway_ip_address)

        if 'delete_operator_cert' in kwargs:
            delete_operator_cert = kwargs['delete_operator_cert']

            self.certifcate_parameters.update(deleteOperatorCert=Validator.validate_param(
                'delete_operator_cert',
                delete_operator_cert.upper(),
                (delete_operator_cert.upper() in ['YES', 'NO'])))

    def as_dict(self):
        attributes = super(AutoconnectionParametersBuilder23C, self).as_dict()
        return attributes
